#include <iostream>
#include <vector>
#include <cstdint>

int64_t count_digits_in_number(int64_t num) {
    num = (num < 0) ? -num : num;
    int64_t count = 0;
    while (num != 0) {
        ++count;
        num /= 10;
    }
    return count;
}

int64_t generate_sequence_of_ones(int64_t length) {
    int64_t result = 0;
    for (int i = 0; i < length; ++i)
        result = result * 10 + 1;
    return result;
}

int64_t recursive_helper2(int64_t num) {
    if (num == 0) return 0;
    num = (num < 0) ? -num : num;
    int64_t d = count_digits_in_number(num);
    return d + recursive_helper2(num - generate_sequence_of_ones(d));
}

int64_t recursive_helper(int64_t n, int64_t s, int64_t acc, int64_t max, std::vector<int>& state) {
    if (acc >= max) return max;
    if (n == 0) return acc;
    if (n < 0) { n = -n; s = -s; }
    int64_t d = count_digits_in_number(n);
    int64_t ones_d = generate_sequence_of_ones(d);
    int64_t res1 = max, res2 = max;

    if (0 <= state[d] * s && -10 < state[d] && state[d] < 10) {
        state[d] += s;
        res1 = recursive_helper(n - ones_d, s, acc + d, max, state);
        state[d] -= s;
    }
    if (0 <= state[d + 1] * s && -10 < state[d + 1] && state[d + 1] < 10) {
        state[d + 1] += s;
        res2 = recursive_helper(n - 10 * ones_d - 1, s, acc + d + 1, res1, state);
        state[d + 1] -= s;
    }
    return res1 < res2 ? res1 : res2;
}

int main() {
    int64_t n;
    std::cin >> n;
    std::vector<int> state(20, 0);
    std::cout << recursive_helper(n, 1, 0, recursive_helper2(n), state) << std::endl;
    return 0;
}
